import{z as d,x as p,o as r,c as B,q as l,j as i,D as t,d as n,s as o,S as m,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"区间树","description":"","frontmatter":{"title":"区间树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interval-tree.md","filePath":"cs/interval-tree.md","lastUpdated":1791413859000}'),E={name:"cs/interval-tree.md"};function D(g,a,h,A,x,b){const s=p("Mermaid");return r(),B("div",null,[a[2]||(a[2]=l('<h1 id="区间树" tabindex="-1">区间树 <a class="header-anchor" href="#区间树" aria-label="Permalink to &quot;区间树&quot;">​</a></h1><div class="epigraph"><p>按区间中点（或左端）建 BST，节点记下子树右端最大值；stabbing 一条查询线时，用最大值剪枝。</p><footer>—— 据 Preparata and Shamos, Computational Geometry；Cormen, Leiserson, Rivest and Stein 第 14.3 节；de Berg et al. 整理</footer></div><p><a href="/cs/y-fast-trie">上一课</a> 回答整数点的前驱后继。现在对象是闭区间 \\([l,r]\\)，询问「哪些区间包含点 \\(q\\)」或「与 \\([a,b]\\) 相交」。本课不把 vEB 当几何。缺口是区间树（interval tree）：与线段树同名易混，这里是<strong>一组区间对象</strong>的字典，不是下标对半。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个区间，点查询 \\(q\\)。暴力 \\(\\Theta(n)\\)。区间树：以左端（或中点）为 BST 键；每个节点额外存<strong>该子树所有区间的最大右端</strong>。查询：若 \\(q\\) 在当前区间内则报告；若左子树 \\(\\mathrm{maxR}\\ge q\\) 则必须进左，否则只进右（因为左端有序，左边左端更小，若最大右端仍 \\(\\lt q\\) 则左边全错过 \\(q\\)）。缺口是<strong>用 maxR 把 BST 查找变成 stabbing</strong>。</p><p><span class="marginnote">CLRS 14.3 用红黑存区间并维护 max。几何书里还有 segment tree（下标/扫描线另一套），名称不要混用本课课名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入删除：BST + 沿路径更新 maxR，平衡与<a href="/cs/order-statistic-tree">顺序统计</a> 维护 size 同模式。报告所有命中最坏 \\(\\Theta(n)\\)（全中）；时间 \\(O(\\log n+k)\\)。只问是否存在相交，可提前停。</p>',8)),(r(),i(m,null,{default:t(()=>[o(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%82%B9%20q%22%5D%20--%3E%20NODE%5B%22%E5%BD%93%E5%89%8D%E5%8C%BA%E9%97%B4%22%5D%0A%20%20NODE%20--%3E%20HIT%5B%22q%20%E8%90%BD%E5%9C%A8%20%5Bl%2Cr%5D%20%E5%88%99%E6%8A%A5%E5%91%8A%22%5D%0A%20%20NODE%20--%3E%20LMAX%5B%22%E5%B7%A6%20maxR%20%3E%3D%20q%3A%20%E5%BF%85%E9%A1%BB%E8%BF%9B%E5%B7%A6%22%5D%0A%20%20NODE%20--%3E%20RGO%5B%22%E5%90%A6%E5%88%99%E5%90%91%E5%8F%B3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 Fenwick/线段树：那些是数组下标上的聚合；本课每个元素自己是一段 \\([l,r]\\)。一维 stabbing 不要用 k-d 树。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：「stabbing 查询」就是拿一根竖针 \\(q\\) 扎穿桌面上一堆横线段，问针扎中了哪几根——每个区间 \\([l,r]\\) 是一根横线段，\\(q\\) 是那根针。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"正确性依赖左端子树键 \\(\\le\\) 当前 \\(\\le\\) 右，以及 maxR 真实。旋转必须修 maxR。坐标若很大可离散化，结构不依赖 vEB。",-1)),a[7]||(a[7]=e("p",null,"重叠极大时 \\(k\\) 大，输出瓶颈，结构帮不上。",-1)),(r(),i(m,null,{default:t(()=>[o(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22(16%2C21)%20maxR%3D30%22%5D%20--%3E%20B%5B%22(8%2C9)%20maxR%3D23%22%5D%0A%20%20A%20--%3E%20C%5B%22(25%2C30)%20maxR%3D30%22%5D%0A%20%20B%20--%3E%20D%5B%22(5%2C8)%20maxR%3D8%22%5D%0A%20%20B%20--%3E%20E%5B%22(15%2C23)%20maxR%3D23%22%5D%0A%20%20C%20--%3E%20F%5B%22(17%2C19)%20maxR%3D19%22%5D%0A%20%20C%20--%3E%20G%5B%22(26%2C26)%20maxR%3D26%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<p><span class="marginnote">数字实例：拿 \\(q=22\\) 扎上图。根 \\((16,21)\\) 没中；但左子树 \\(\\mathrm{maxR}=23\\ge 22\\)，必须下左；\\((8,9)\\) 没中，其左孩子 \\(\\mathrm{maxR}=8\\lt 22\\) 整枝剪掉，下右；\\((15,23)\\) 命中报告。只走了 3 个节点就答完，没碰右子树。</span></p><p><span class="marginnote">常见误区：初学者容易以为节点只存自己的右端就够——不行。\\(\\mathrm{maxR}\\) 是<strong>整棵子树</strong>的最大右端，父子间传递查询剪枝全靠它；旋转时父子换了位置，必须先重算孩子、再重算自己，漏一边整棵树的剪枝就失效。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写区间树套动态树、或三维。正交矩形范围查询下一课 k-d 树与后课 R 树。点集矩形查询与区间 stabbing 选错结构会多一个 \\(\\log\\)。</p><p>后课默认：一维区间包含用区间树。平面点的正交范围用 k-d 树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>区间树：BST（左端）+ 子树 maxR，stabbing \\(O(\\log n+k)\\)。</li><li>与下标线段树不是同一结构。</li><li>平面点范围查询交给 k-d 树。</li><li>出处：Preparata and Shamos；Cormen et al. 14.3。</li></ul>',7))])}const T=d(E,[["render",D]]);export{f as __pageData,T as default};
